@Service
@RequiredArgsConstructor
class AvisoS016Service {
    private final S016CuentasClient s016;     // S016 L428
    private final P050Properties props;

    @Transactional
    ResultadoS016 envia(Aviso a) {
        return switch (a.tipoRegistro()) {
            case 2 -> (a.estatusContrato() == 10 || a.estatusContrato() == 11)
                        ? activaCuenta(a)                       // 50204310
                        : marcaBeneficencia(a);                 // 50204320
            case 4  -> reactivaContratoOrigen(a);               // 50204340
            default -> actualizaOpcionRiesgoPago(a);            // 50204300-ENVIA-ACTLZA-S016
        };
    }

    private ResultadoS016 activaCuenta(Aviso a) {
        if (props.esSinActivacion(a.producto(), a.instrumento())) {
            return ResultadoS016.de(25);                        // 66/11: no se llama a S016
        }
        int r = s016.activaCuentaYMedio(a.producto(), a.instrumento(), a.contrato(),
                                        a.estatusContrato(), a.estatusMedio());   // B04CTAB08MDA
        return ResultadoS016.de(r);
    }
}

