private ResultadoS016 marcaBeneficencia(Aviso a) {           // 50204320 -> STA-BENEFICENCIA
    int r = s016.estatusBeneficencia(a.producto(), a.instrumento(),
                                     a.prefijoContrato(), a.numeroContrato(), a.estatusContrato());
    return ResultadoS016.de(r);
}

private ResultadoS016 reactivaContratoOrigen(Aviso a) {      // 50204340 -> STA-BENEFICENCI2
    int r = s016.estatusBeneficencia2(a.producto(), a.instrumento(),
                                      a.prefijoContrato(), a.numeroContrato(), a.estatusContrato(),
                                      props.reactivacion().paso(), props.reactivacion().caja());
    return ResultadoS016.de(r);
}

/** 50204300-ASIGNA-RESULT-S016: resultado de S016 a WS-INDRES-S016 (estatus de envío). */
public record ResultadoS016(int resultado, int indicador) {
    public static ResultadoS016 de(int r) {
        int ind;
        if (r == 0)                 ind = 20;     // aplicado
        else if (r > 0 && r < 20)   ind = r;      // error de negocio, se conserva
        else if (r == 25)           ind = 25;     // producto sin activación
        else if (r > 79 && r < 99)  ind = 21;
        else if (r > 99)            ind = 22;
        else                        ind = 23;     // 20..24, 26..79 y 99
        return new ResultadoS016(r, ind);
    }
}

private ResultadoS016 actualizaOpcionRiesgoPago(Aviso a) {      // 50204300-ENVIA-ACTLZA-S016
    // El fuente envía siempre producto 1, instrumento 3 y opción 70, sin importar el aviso.
    var cfg = props.actualizaPago();                             // producto: 1, instrumento: 3, opcion: 70
    int r = s016.actualizaCuenta(cfg.producto(), cfg.instrumento(), a.contrato(), cfg.opcion(),
                                 a.opcionPago(), a.riesgoPago());   // B04CUENTAS
    // Aquí solo hay dos indicadores posibles: 20 aplicado o 23 error.
    return new ResultadoS016(r, r == 0 ? 20 : 23);
}

