@Component
@RequiredArgsConstructor
class BitacoraProcesados {
    private final AvisoProcesadoRepository repo;

    @Transactional(propagation = Propagation.MANDATORY)    // misma transacción que el envío
    void graba(Aviso a, ResultadoS016 r) { repo.save(AvisoProcesado.de(a, r, LocalDateTime.now())); }
}
